            r#"<div class="breadcrumbs"><a href="/moderate">← All quizzes</a></div><div class="page-head"><h1>New quiz</h1></div><div class="card"><div class="errors">Title can&apos;t be blank</div><form method="post" action="/moderate/quizzes"><div class="field"><label for="title">Title</label><input class="input" type="text" id="title" name="title" value="" required></div><div class="buttons"><button class="btn btn--pink" type="submit">Save quiz</button><a class="btn btn--ghost" href="/moderate">Cancel</a></div></form></div>"#
