async fn show_quiz_handler(
    State(state): State<AppState>,
    Path(id): Path<i64>,
) -> impl IntoResponse {
    let conn = db_connect(&state).unwrap();
    let Some(quiz) = get_quiz(&conn, id) else {
        return (StatusCode::NOT_FOUND, Html(admin_layout("Not found", "<h1>Quiz not found</h1>"))).into_response();
    };
    let questions = list_questions(&conn, id);
    let (total, active_count) = count_questions(&conn, id);
    // Build questions list
    let mut qhtml = String::new();
    if questions.is_empty() {
        qhtml.push_str(r#"<div class="empty">No questions yet.</div>"#);
    } else {
        qhtml.push_str(r#"<ul class="question-list">"#);
        let mut active_num = 0;
        for q in questions.iter() {
            let opts = list_options(&conn, q.id);
            let num_display = if q.active {
                active_num += 1;
                active_num.to_string()
            } else {
                "—".to_string()
            };
            let inactive_class = if q.active { "" } else { " question-item--inactive" };
            // options
            let mut ohtml = String::new();
            for (oi, o) in opts.iter().enumerate() {
                let letter = letter_for(oi);
                let cls = if o.is_correct { r#" class="is-correct""# } else { "" };
                ohtml.push_str(&format!(
                    r#"<li{}>{}. {}</li>"#,
                    cls,
                    letter,
                    html_escape(&o.body)
                ));
            }
            let checked = if q.active { " checked" } else { "" };
            qhtml.push_str(&format!(
                r#"<li class="card question-item{}"><div class="question-item__num">{}</div><div><div class="question-item__body">{}</div><ul class="question-item__options">{}</ul></div><div class="question-item__actions"><div class="buttons"><form method="post" action="/moderate/quizzes/{}/questions/{}/move-up"><button class="btn btn--ghost btn--sm" type="submit">Move up</button></form><form method="post" action="/moderate/quizzes/{}/questions/{}/move-down"><button class="btn btn--ghost btn--sm" type="submit">Move down</button></form></div><form method="post" action="/moderate/quizzes/{}/questions/{}/active"><input type="hidden" name="_form" value="1"><label class="checkbox"><input type="checkbox" name="active" value="on"{} onchange="this.form.submit()"> Active</label></form><div class="buttons"><a class="btn btn--sm" href="/moderate/quizzes/{}/questions/{}/edit">Edit</a><form method="post" action="/moderate/quizzes/{}/questions/{}/delete" onsubmit="return confirm('Delete this question?')"><button class="btn btn--sm btn--danger" type="submit">Delete</button></form></div></div></li>"#,
                inactive_class,
                num_display,
                html_escape(&q.body),
                ohtml,
                id, q.id,
                id, q.id,
                id, q.id, checked,
                id, q.id,
                id, q.id
            ));
        }
        qhtml.push_str("</ul>");
    }

    let body = format!(
        r#"<div class="breadcrumbs"><a href="/moderate">← All quizzes</a></div><div class="page-head"><div><h1>{}</h1><div class="meta">{} of {} questions active · <a href="/moderate/quizzes/{}/settings">Settings</a></div></div><div class="buttons"><a class="btn btn--ghost" href="/moderate/quizzes/{}/preview">Preview</a></div></div><section class="section mt-0"><div class="section-head"><h2>Questions</h2><a class="btn" href="/moderate/quizzes/{}/questions/new">Add question</a></div>{}</section>"#,
        html_escape(&quiz.title),
        active_count,
        total,
        id,
        id,
        id,
        qhtml
    );
    Html(admin_layout(&quiz.title, &body)).into_response()
}

